using FinanSmart.Api.Common.Enums;using FinanSmart.Api.Common.Exceptions;using FinanSmart.Api.Data.Context;using FinanSmart.Api.Modules.Investments.Rates.Interfaces;using FinanSmart.Api.Modules.Investments.Simulations.DTOs;using FinanSmart.Api.Modules.Investments.Simulations.Interfaces;using Microsoft.EntityFrameworkCore;
namespace FinanSmart.Api.Modules.Investments.Simulations.Services;public class InvestmentSimulationService(FinanSmartDbContext db,IInvestmentRateService rates):IInvestmentSimulationService{public async Task<InvestmentSimulationResponseDto> SimulateAsync(InvestmentSimulationRequestDto r){var p=await db.InvestmentProducts.FindAsync(r.InvestmentProductId)??throw new InvestmentProductNotFoundException();if(!p.IsActive||r.Amount<=0||r.TermDays<=0||r.Amount<p.MinimumAmount||(p.MaximumAmount.HasValue&&r.Amount>p.MaximumAmount)||r.TermDays<p.MinimumTermDays||(p.MaximumTermDays.HasValue&&r.TermDays>p.MaximumTermDays))throw new ArgumentException("Invalid investment parameters.");var rate=await rates.GetApplicableRateAsync(p.Id,r.Amount,r.TermDays)??throw new InvestmentProductNotFoundException();var start=r.StartDate??DateTimeOffset.UtcNow;var factor=(decimal)r.TermDays/365m;var interest=p.InterestCalculationMethod==InterestCalculationMethod.Simple?r.Amount*(rate.AnnualInterestRate/100m)*factor:(decimal)((double)r.Amount*(Math.Pow(1+(double)(rate.AnnualInterestRate/100m),(double)factor)-1));var schedule=Schedule(start,r.TermDays,interest,p.InterestPaymentFrequency);return new(){InvestmentProductId=p.Id,InvestmentProductName=p.Name,Principal=r.Amount,TermDays=r.TermDays,AnnualInterestRate=rate.AnnualInterestRate,InterestCalculationMethod=p.InterestCalculationMethod,InterestPaymentFrequency=p.InterestPaymentFrequency,StartDate=start,MaturityDate=start.AddDays(r.TermDays),TotalInterest=interest,PrincipalAtMaturity=r.Amount,TotalReceived=r.Amount+interest,PaymentCount=schedule.Count,PaymentSchedule=schedule,GeneratedAt=DateTimeOffset.UtcNow};}private static List<InvestmentPaymentDto> Schedule(DateTimeOffset s,int days,decimal interest,InterestPaymentFrequency f){var maturity=s.AddDays(days);if(f==InterestPaymentFrequency.Upfront)return[new(){PaymentNumber=1,PaymentDate=s,PaymentType="Upfront",InterestAmount=interest}];var months=f==InterestPaymentFrequency.Monthly?1:f==InterestPaymentFrequency.Quarterly?3:f==InterestPaymentFrequency.SemiAnnual?6:0;if(months==0)return[new(){PaymentNumber=1,PaymentDate=maturity,PaymentType="Maturity",InterestAmount=interest}];var dates=new List<DateTimeOffset>();for(var d=s.AddMonths(months);d<maturity;d=d.AddMonths(months))dates.Add(d);dates.Add(maturity);var result=new List<InvestmentPaymentDto>();decimal assigned=0;for(var i=0;i<dates.Count;i++){var value=i==dates.Count-1?interest-assigned:decimal.Round(interest/dates.Count,2);assigned+=value;result.Add(new(){PaymentNumber=i+1,PaymentDate=dates[i],PaymentType=i==dates.Count-1?"Maturity":"Interest",InterestAmount=value});}return result;}}
